using JobOrbit.Application.DTOs.AdminUsers;using JobOrbit.Application.Interfaces;using JobOrbit.Domain.Entities;using JobOrbit.Domain.Enums;using Microsoft.AspNetCore.Identity;
namespace JobOrbit.Application.Services;public sealed class AdminUserService(IAdminUserRepository repository,IPasswordHasher<User>hasher):IAdminUserService
{static bool Role(string?value,out UserRole role){if(string.Equals(value,"Admin",StringComparison.OrdinalIgnoreCase)){role=UserRole.Administrator;return true;}return Enum.TryParse(value,true,out role);}public async Task<(bool Valid,Application.DTOs.Jobs.PagedResultDto<AdminUserListItemDto>?Result)>ListAsync(AdminUserQuery q,CancellationToken t=default){UserRole?role=null;if(!string.IsNullOrWhiteSpace(q.Role)){if(!Role(q.Role,out var parsed))return(false,null);role=parsed;}bool?active=q.Status?.ToLowerInvariant()switch{"active"=>true,"inactive"=>false,""or null=>null,_=>(bool?)null};if(!string.IsNullOrWhiteSpace(q.Status)&&q.Status is not("Active"or"Inactive")&&!q.Status.Equals("active",StringComparison.OrdinalIgnoreCase)&&!q.Status.Equals("inactive",StringComparison.OrdinalIgnoreCase))return(false,null);q.Page=Math.Max(1,q.Page);q.PageSize=Math.Clamp(q.PageSize,1,50);return(true,await repository.ListAsync(q,role,active,t));}public Task<AdminUserDetailsDto?>DetailsAsync(int id,CancellationToken t=default)=>repository.DetailsAsync(id,t);public async Task<AdminUserMutationResult>CreateAsync(int admin,CreateAdminUserRequest r,CancellationToken t=default){if(!Role(r.Role,out var role))return new(AdminUserMutationOutcome.InvalidRole);var temp=new User{Email=r.Email.Trim().ToLowerInvariant(),FirstName=r.FirstName.Trim(),LastName=r.LastName.Trim(),Role=role};return await repository.CreateAsync(admin,r,role,hasher.HashPassword(temp,r.TemporaryPassword),t);}public Task<AdminUserMutationResult>UpdateAsync(int admin,int id,UpdateAdminUserRequest r,CancellationToken t=default)=>Role(r.Role,out var role)?repository.UpdateAsync(admin,id,r,role,t):Task.FromResult(new AdminUserMutationResult(AdminUserMutationOutcome.InvalidRole));public Task<AdminUserMutationResult>StatusAsync(int admin,int id,UpdateUserStatusRequest r,CancellationToken t=default)=>repository.StatusAsync(admin,id,r,t);public async Task<AdminUserMutationOutcome>ResetPasswordAsync(int admin,int id,AdminResetPasswordRequest r,CancellationToken t=default){var user=await repository.UserForPasswordAsync(id,t);if(user is null)return AdminUserMutationOutcome.NotFound;return await repository.ResetPasswordAsync(admin,id,hasher.HashPassword(user,r.TemporaryPassword),t);}}
